class _EnumEntry(object):
    def __init__(self, enum, name, value):
        self.enum = enum
        self.name = name
        self.value = value
    def __get__(self, obj, type=None):
        return self
    def __repr__(self):
        return "{0}.{1}".format(self.enum, self.name)
    @property
    def __name__(self):
        return None
    @__name__.setter
    def __name__(self, value):
        pass
    @property
    def __doc__(self):
        return None
    @__doc__.setter
    def __doc__(self, value):
        pass

