    COND_SIMULATED_OR_PHYSICS = _EnumEntry("LifetimeCondition", "COND_SIMULATED_OR_PHYSICS", 6)  #: 6: This property will only send to autonomous actors
    COND_INITIAL_OR_OWNER = _EnumEntry("LifetimeCondition", "COND_INITIAL_OR_OWNER", 7)  #: 7: This property will send to simulated OR bRepPhysics actors
    COND_CUSTOM = _EnumEntry("LifetimeCondition", "COND_CUSTOM", 8)  #: 8: This property will send on the initial packet, or to the actors owner
    COND_REPLAY_OR_OWNER = _EnumEntry("LifetimeCondition", "COND_REPLAY_OR_OWNER", 9)  #: 9: This property has no particular condition, but wants the ability to toggle on/off via SetCustomIsActiveOverride
    COND_REPLAY_ONLY = _EnumEntry("LifetimeCondition", "COND_REPLAY_ONLY", 10)  #: 10: This property will only send to the replay connection, or to the actors owner
    COND_SIMULATED_ONLY_NO_REPLAY = _EnumEntry("LifetimeCondition", "COND_SIMULATED_ONLY_NO_REPLAY", 11)  #: 11: This property will only send to the replay connection
    COND_SIMULATED_OR_PHYSICS_NO_REPLAY = _EnumEntry("LifetimeCondition", "COND_SIMULATED_OR_PHYSICS_NO_REPLAY", 12)  #: 12: This property will send to actors only, but not to replay connections
    COND_SKIP_REPLAY = _EnumEntry("LifetimeCondition", "COND_SKIP_REPLAY", 13)  #: 13: This property will send to simulated Or bRepPhysics actors, but not to replay connections
    pass

