    ORIENTATION = _EnumEntry("ARSessionType", "ORIENTATION", 1)  #: 1: A session where only the orientation of the device is tracked. ARKit supports this type of tracking.
    WORLD = _EnumEntry("ARSessionType", "WORLD", 2)  #: 2: A session where the position and orientation of the device is tracked relative to objects in the environment. All platforms support this type of tracking.
    FACE = _EnumEntry("ARSessionType", "FACE", 3)  #: 3: A session where only faces are tracked. ARKit and ARCore support this type of tracking using the front-facing camera.
    IMAGE = _EnumEntry("ARSessionType", "IMAGE", 4)  #: 4: A session where only images supplied by the app are tracked. There is no world tracking. ARKit supports this type of tracking.
    OBJECT_SCANNING = _EnumEntry("ARSessionType", "OBJECT_SCANNING", 5)  #: 5: A session where objects are scanned for object detection in a later World Tracking session. ARKit supports this type of tracking.
    POSE_TRACKING = _EnumEntry("ARSessionType", "POSE_TRACKING", 6)  #: 6: A session where human poses in 3D are tracked. ARKit supports this type of tracking using the rear-facing camera.
    GEO_TRACKING = _EnumEntry("ARSessionType", "GEO_TRACKING", 7)  #: 7: A session where geographic locations are tracked. ARKit supports this type of tracking.
    pass

