    TO_ZERO = _EnumEntry("RoundingMode", "TO_ZERO", 4)  #: 4: Rounds to the value which is closer to zero, "smaller" in absolute value: 0.1 becomes 0, -0.1 becomes 0
    TO_NEGATIVE_INFINITY = _EnumEntry("RoundingMode", "TO_NEGATIVE_INFINITY", 5)  #: 5: Rounds to the value which is more negative: 0.1 becomes 0, -0.1 becomes -1
    TO_POSITIVE_INFINITY = _EnumEntry("RoundingMode", "TO_POSITIVE_INFINITY", 6)  #: 6: Rounds to the value which is more positive: 0.1 becomes 1, -0.1 becomes 0
    pass

