    def address_x(self, value):
        pass
    @property
    def address_y(self):
        r"""
        (TextureAddress):  [Read-Write] Address Y:
        The addressing mode to use for the Y axis.
        """
        return TextureAddress.TA_WRAP
    @address_y.setter
    def address_y(self, value):
        pass
    def blueprint_get_size_y(self):
        r"""
        x.blueprint_get_size_y() -> int32
        Gets the Y size of the texture, in pixels
        
        Returns:
            int32:
        """
        return 0
    def blueprint_get_size_x(self):
        r"""
        x.blueprint_get_size_x() -> int32
        Gets the X size of the texture, in pixels
        
        Returns:
            int32:
        """
        return 0

