    @property
    def imported_sequences(self):
        r"""
        (Array(LevelSequence)):  [Read-Write] Imported Sequences
        """
        return Array.cast(LevelSequence, [])
    @imported_sequences.setter
    def imported_sequences(self, value):
        pass
    def play_level_sequence(self, sequence_to_play):
        r"""
        x.play_level_sequence(sequence_to_play) -> None
        Play Level Sequence
        
        Args:
            sequence_to_play (LevelSequence):
        """
        return None

